<?php
if(!defined('ABSPATH'))exit;
function dgs_elementor_register_assets(){
 if(!wp_style_is('dgs-showcase','registered')){wp_register_style('dgs-showcase',false,array(),DGS_VERSION);wp_add_inline_style('dgs-showcase',str_replace('SHOWCASE_REFERENCE_URL',esc_url_raw(DGS_URL.'assets/showcase-reference.jpg'),file_get_contents(DGS_PATH.'assets/showcase.css')));}
 if(!wp_script_is('dgs-showcase','registered')){wp_register_script('dgs-showcase',false,array(),DGS_VERSION,true);wp_add_inline_script('dgs-showcase',file_get_contents(DGS_PATH.'assets/showcase.js'));}
 if(!wp_style_is('dgs-elementor-design','registered')){wp_register_style('dgs-elementor-design',false,array(),DGS_VERSION);wp_add_inline_style('dgs-elementor-design',file_get_contents(DGS_PATH.'assets/elementor-design.css'));}
}
add_action('wp_enqueue_scripts','dgs_elementor_register_assets',5);
add_action('elementor/widgets/register',function($manager){require_once DGS_PATH.'includes/elementor-widgets.php';$manager->register(new DGS_Elementor_Live_Widget());$manager->register(new DGS_Elementor_Picture_Widget());$manager->register(new DGS_Elementor_Icon_Widget());});
function dgs_elementor_live_render($s){
 $kind=$s['kind']??'teachers';$count=max(1,min(30,absint($s['count']??6)));$out='';
 if(in_array($kind,array('teachers','staff'),true)){$posts=$kind==='teachers'?dgs_showcase_teacher_posts($count):dgs_showcase_staff();if($kind==='staff'&&($s['staff_group']??'')==='deputies')$posts=array_values(array_filter($posts,function($p){return strpos(get_post_meta($p->ID,'_dgs_specialty',true),'معاون')!==false;}));$posts=array_slice($posts,0,$count);$carousel=($s['carousel']??'')==='yes';$people=dgs_showcase_people($posts,$carousel?'dsh-people-scroll':'dse-live-grid dsh-team-cards',$kind==='staff');$out=$carousel?'<div class="dsh-carousel"><div class="dsh-carousel-controls"><button type="button" data-dsh-scroll="prev" aria-label="قبلی">‹</button><button type="button" data-dsh-scroll="next" aria-label="بعدی">›</button></div>'.$people.'</div>':$people;}
 elseif($kind==='gallery'){$out=dgs_gallery_preview($count,$s);}
 elseif($kind==='featured'){$out=dgs_showcase_featured();$uid=wp_unique_id('dse-star-');$out=preg_replace('/<div class="dsh-strip-copy">.*?<\/div>/su','',$out,1);$out=str_replace(array('id="dsh-tab-','id="dsh-star-','aria-controls="dsh-star-','aria-labelledby="dsh-tab-'),array('id="'.$uid.'tab-','id="'.$uid.'panel-','aria-controls="'.$uid.'panel-','aria-labelledby="'.$uid.'tab-'),$out);$out=str_replace('dsh-card dsh-featured','dse-featured',$out);}
 elseif($kind==='news'){$type=($s['category']??'school')==='ministry'?'ministry':'school';$posts=get_posts(array('post_type'=>'post','post_status'=>'publish','numberposts'=>$count,'category_name'=>$type==='school'?'school-news':'ministry-news','ignore_sticky_posts'=>true));foreach($posts as $p){$out.='<article class="dsh-news-row">';if(has_post_thumbnail($p))$out.='<a class="dsh-news-photo" href="'.esc_url(get_permalink($p)).'">'.get_the_post_thumbnail($p,'thumbnail',array('loading'=>'lazy')).'</a>';$out.='<div><h3><a href="'.esc_url(get_permalink($p)).'">'.esc_html($p->post_title).'</a></h3><small>'.esc_html(dgs_display_date(get_post_timestamp($p))).'</small></div></article>';}if(!$posts)$out=dgs_empty('خبری در این گروه منتشر نشده است.');}
 elseif($kind==='director'){$staff=dgs_showcase_staff();$id=absint($s['director_id']??0);$person=null;if($id){foreach($staff as $p)if($p->ID===$id)$person=$p;}else $person=dgs_showcase_director($staff);if($person){$text=!empty($s['director_text'])?sanitize_textarea_field($s['director_text']):wp_strip_all_tags($person->post_content);$out='<div class="dsh-director-row"><div class="dsh-director-photo">'.dgs_avatar($person->ID,'large').'</div><div><h3>'.esc_html($person->post_title).'</h3><p>'.nl2br(esc_html($text)).'</p></div></div>';}else $out=dgs_empty('اطلاعات مدیر هنوز منتشر نشده است.');}
 elseif($kind==='contact'){foreach(array('address'=>array('pin','نشانی'),'phone'=>array('phone','تلفن'),'office_hours'=>array('timetable','ساعات پاسخ‌گویی')) as $key=>$v){$value=dgs_setting($key);if($value)$out.='<p class="dse-contact-line">'.dgs_portal_icon($v[0]).'<b>'.esc_html($v[1]).':</b> '.esc_html($value).'</p>';}}
 return '<div class="dse-live">'.$out.'</div>';
}
function dgs_elementor_picture_render($s){$image=$s['image']??array();$image=is_array($image)?$image:array();$id=absint($image['id']??0);$url=is_string($image['url']??null)?esc_url($image['url'],array('http','https')):'';$alt=sanitize_text_field($s['alt']??'');$caption=sanitize_text_field($s['caption']??'');$priority=($s['priority']??'')==='yes';$ref=$s['reference']??'hero';$reference=!$url&&!dgs_showcase_image_valid($id);$class='dsh-hero-picture';if(preg_match('/^gallery([0-3])$/D',$ref,$m))$class='dsh-gallery-photo dsh-reference-'.$m[1];$out='<figure class="dse-picture"><div class="dse-picture-frame '.($reference?'dsh-picture dsh-reference '.esc_attr($class):'').'">';if(dgs_showcase_image_valid($id))$out.=wp_get_attachment_image($id,'large',false,array('alt'=>$alt,'loading'=>$priority?'eager':'lazy','fetchpriority'=>$priority?'high':'auto'));elseif($url)$out.='<img src="'.$url.'" alt="'.esc_attr($alt).'" loading="'.($priority?'eager':'lazy').'" decoding="async">';else $out.='<span class="screen-reader-text">'.esc_html($alt.' — تصویر نمایشی طرح').'</span>';$out.='</div>';if($caption)$out.='<figcaption>'.esc_html($caption).'</figcaption>';return $out.'</figure>';}
function dgs_elementor_targets(){$p=get_option('dgs_pages',array());if(get_option('show_on_front')==='page'&&get_option('page_on_front'))$p['home']=(int)get_option('page_on_front');return array_intersect_key($p,array('home'=>true,'about'=>true));}
function dgs_elementor_converted($id=0){return get_post_meta($id?:get_queried_object_id(),'_dgs_elementor_showcase',true)==='1';}
function dgs_elementor_snapshot($id){$meta=array();foreach(array('_elementor_data','_elementor_edit_mode','_elementor_page_settings','_elementor_template_type','_elementor_version','_wp_page_template','_dgs_elementor_showcase') as $key)$meta[$key]=array('exists'=>metadata_exists('post',$id,$key),'value'=>get_post_meta($id,$key,true));return array('content'=>get_post_field('post_content',$id),'meta'=>$meta);}
function dgs_elementor_restore_snapshot($id,$backup){foreach($backup['meta'] as $key=>$data){if($data['exists'])update_post_meta($id,$key,wp_slash($data['value']));else delete_post_meta($id,$key);}wp_update_post(wp_slash(array('ID'=>$id,'post_content'=>$backup['content'])));delete_post_meta($id,'_elementor_css');clean_post_cache($id);dgs_catalog_invalidate($id);}
function dgs_elementor_prepare_pages(){
 if(!current_user_can('manage_options'))return new WP_Error('access','دسترسی ندارید.');if(!class_exists('\\Elementor\\Plugin'))return new WP_Error('elementor','ابتدا افزونه المنتور را فعال کنید.');$pages=dgs_elementor_targets();if(count($pages)!==2||count(array_unique($pages))!==2)return new WP_Error('pages','برگه‌های خانه و معرفی باید در راه‌انداز سامانه مشخص باشند.');foreach($pages as $id)if(get_post_type($id)!=='page'||!current_user_can('edit_post',$id)||get_post_status($id)==='trash')return new WP_Error('page','برگه قابل ویرایش نیست.');
 \Elementor\Plugin::$instance->widgets_manager->get_widget_types();$changed=array();$snapshots=array();try{foreach($pages as $key=>$id){if(dgs_elementor_converted($id))continue;$backup=dgs_elementor_snapshot($id);$snapshots[$id]=$backup;if(!metadata_exists('post',$id,'_dgs_elementor_backup_018')){update_post_meta($id,'_dgs_elementor_backup_018',wp_slash($backup));if(get_post_meta($id,'_dgs_elementor_backup_018',true)!==$backup)throw new Exception('پشتیبان صفحه ساخته نشد.');}$data=dgs_elementor_showcase_data($key);$doc=\Elementor\Plugin::$instance->documents->get($id);if(!$doc)throw new Exception('سند المنتور در دسترس نیست.');$changed[]=$id;update_post_meta($id,'_elementor_edit_mode','builder');update_post_meta($id,'_wp_page_template','default');$result=$doc->save(array('elements'=>$data,'settings'=>array('hide_title'=>'yes')));if(!$result||!get_post_meta($id,'_elementor_data',true))throw new Exception('ذخیره طرح المنتور کامل نشد.');update_post_meta($id,'_dgs_elementor_showcase','1');if(!dgs_elementor_converted($id))throw new Exception('ثبت وضعیت صفحه انجام نشد.');delete_post_meta($id,'_elementor_css');dgs_catalog_invalidate($id);}}
 catch(Throwable $e){foreach($changed as $id)dgs_elementor_restore_snapshot($id,$snapshots[$id]);return new WP_Error('save',$e->getMessage());}if(class_exists('\\Elementor\\Plugin'))\Elementor\Plugin::$instance->files_manager->clear_cache();return $pages;
}
add_action('admin_menu',function(){add_submenu_page('dgs-setup','ویرایش صفحات با المنتور','ویرایش با المنتور','manage_options','dgs-elementor-design','dgs_elementor_design_page');});
function dgs_elementor_design_page(){if(!current_user_can('manage_options'))wp_die('دسترسی ندارید.');$pages=dgs_elementor_targets();echo '<div class="wrap" style="max-width:1000px"><h1>صفحه اصلی و معرفی در المنتور</h1><p>پس از آماده‌سازی، عنوان‌ها، متن‌ها، دکمه‌ها، تصاویر، امکانات و چیدمان از خود المنتور و المنتور پرو تغییر می‌کنند. اطلاعات اساتید، کادر، برگزیده و اخبار با ویجت‌های زنده به سامانه وصل می‌مانند.</p>';if(isset($_GET['dse_notice'])){echo '<div class="notice notice-info"><p>'.esc_html(dgs_catalog_get('dse_notice')).'</p></div>';}$ready=count($pages)===2;foreach($pages as $id)$ready=$ready&&dgs_elementor_converted($id);if(!$ready)echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dgs_elementor_prepare">'.wp_nonce_field('dgs_elementor_prepare','dgs_elementor_nonce',true,false).'<p>طرح فعلی به اجزای قابل ویرایش تبدیل می‌شود. از محتوای قبلی هر برگه پشتیبان داخلی نگه‌داری می‌شود؛ آدرس و شناسه برگه‌ها ثابت می‌مانند. دوباره‌زدن دکمه، صفحه‌ای را که قبلاً تبدیل شده بازنویسی نمی‌کند.</p><button class="button button-primary">آماده‌سازی دو صفحه برای المنتور</button></form>';
 foreach($pages as $key=>$id)echo '<h2>'.($key==='home'?'صفحه اصلی':'معرفی مدرسه').'</h2><p>وضعیت: '.(dgs_elementor_converted($id)?'قابل ویرایش در المنتور':'هنوز تبدیل نشده').'</p><a class="button button-primary" href="'.esc_url(admin_url('post.php?post='.(int)$id.'&action=elementor')).'">ویرایش با المنتور</a> <a class="button" href="'.esc_url(get_permalink($id)).'">مشاهده صفحه</a>';
 if($ready)echo '<details style="margin-top:25px"><summary>بازگردانی طرح قبل از تبدیل</summary><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dgs_elementor_restore">'.wp_nonce_field('dgs_elementor_restore','dgs_elementor_nonce',true,false).'<p>بازگردانی، ویرایش‌های فعلی المنتور این دو صفحه را با پشتیبان قبل از تبدیل جایگزین می‌کند. یک نسخه از ویرایش فعلی نیز نگه‌داری می‌شود.</p><button class="button" onclick="return confirm(\'طرح پیش از تبدیل بازگردانی شود؟\')">بازگردانی پشتیبان</button></form></details>';echo '</div>';}
function dgs_elementor_admin_guard($nonce){if(!current_user_can('manage_options'))wp_die('دسترسی ندارید.','',array('response'=>403));if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('روش معتبر نیست.','',array('response'=>405));check_admin_referer($nonce,'dgs_elementor_nonce');}
add_action('admin_post_dgs_elementor_prepare',function(){dgs_elementor_admin_guard('dgs_elementor_prepare');if(!add_option('dgs_elementor_conversion_lock',time(),'','no')){if((int)get_option('dgs_elementor_conversion_lock')<time()-180)delete_option('dgs_elementor_conversion_lock');wp_die('آماده‌سازی در حال انجام است؛ کمی بعد دوباره تلاش کنید.');}try{$result=dgs_elementor_prepare_pages();}finally{delete_option('dgs_elementor_conversion_lock');}$notice=is_wp_error($result)?$result->get_error_message():'دو صفحه آماده شد؛ اکنون آن‌ها را در المنتور ویرایش کنید.';wp_safe_redirect(add_query_arg('dse_notice',$notice,admin_url('admin.php?page=dgs-elementor-design')),303);exit;});
add_action('admin_post_dgs_elementor_restore',function(){dgs_elementor_admin_guard('dgs_elementor_restore');foreach(dgs_elementor_targets() as $id){$backup=get_post_meta($id,'_dgs_elementor_backup_018',true);if(!is_array($backup)||!isset($backup['content'],$backup['meta']))continue;update_post_meta($id,'_dgs_elementor_before_restore',wp_slash(dgs_elementor_snapshot($id)));dgs_elementor_restore_snapshot($id,$backup);}if(class_exists('\\Elementor\\Plugin'))\Elementor\Plugin::$instance->files_manager->clear_cache();wp_safe_redirect(admin_url('admin.php?page=dgs-elementor-design'),303);exit;});
add_filter('body_class',function($classes){if(dgs_showcase_active()&&dgs_elementor_converted())$classes[]='dse-editable';return $classes;});
add_action('wp_enqueue_scripts',function(){if(!dgs_showcase_active()||!dgs_elementor_converted())return;dgs_elementor_register_assets();wp_enqueue_style('dgs-elementor-design');$styles=wp_styles();$after=$styles->get_data('daneshgaran','after');if(is_array($after)){$after=array_map(function($css){return str_replace('body.dg-site .elementor-widget-heading','body.dg-site:not(.dse-editable) .elementor-widget-heading',$css);},$after);$styles->add_data('daneshgaran','after',$after);}},120);
foreach(array('dgs_elementor_prepare','dgs_elementor_restore') as $dgs_elementor_action)add_action('admin_post_nopriv_'.$dgs_elementor_action,function(){wp_die('دسترسی ندارید.','',array('response'=>403));});
add_action('elementor/editor/after_save',function($id){if(dgs_elementor_converted($id))dgs_catalog_invalidate($id);},100);
